th)?> включительно?">Завершить после месяца</button><?php endif; ?><?php if($p['IS_SKIPPED']): ?><button name="mode" value="restore">Вернуть в месяц</button><?php else: ?><button name="mode" value="skip" data-confirm="Исключить только этот месяц?">Исключить месяц</button><?php endif; ?><?php if($p['HAS_MONTH_OVERRIDE']): ?><button name="mode" value="clear" data-confirm="Убрать месячное исключение условий?">Убрать исключение</button><?php endif; ?><label>Для удаления введите УДАЛИТЬ<input name="confirm" maxlength="30"></label><button name="mode" value="delete" class="danger" data-confirm="Удалить всю серию? Только без времени.">Удалить полностью</button></div></form></details></article><?php endforeach; ?><?php if(!$b['packages']): ?><div class="empty">Пакетов на этот месяц нет.</div><?php endif; ?></div><section><h2>Все абонентские пакеты</h2><div class="subscription-list"><?php foreach($r->rows('packages',['=UF_CLIENT'=>$client,'=UF_REPEAT'=>1]) as $p): ?><div class="subscription-row"><div><b><?=$h($p['UF_NAME'])?></b><small>С <?=$h($p['UF_MONTH'])?> · <?=!empty($p['UF_END_MONTH'])?'по '.$h($p['UF_END_MONTH']):'до остановки'?> · #<?=(int)$p['ID']?></small></div><a data-form="drawer" class="button small" href="<?=$h($url('/clients/period.php',['client'=>$client,'id'=>(int)$p['ID'],'month'=>$month]))?>">Срок / удаление</a></div><?php endforeach; ?></div></section>
